import{_ as n,H as a,f as p,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"特别放送｜手把手带你阅读ChatGPT接口","description":"","frontmatter":{},"headers":[{"level":2,"title":"接口地址","slug":"接口地址","link":"#接口地址","children":[]},{"level":2,"title":"请求","slug":"请求","link":"#请求","children":[{"level":3,"title":"model","slug":"model","link":"#model","children":[]},{"level":3,"title":"message","slug":"message","link":"#message","children":[]},{"level":3,"title":"temperature","slug":"temperature","link":"#temperature","children":[]},{"level":3,"title":"top_p","slug":"top-p","link":"#top-p","children":[]},{"level":3,"title":"n","slug":"n","link":"#n","children":[]},{"level":3,"title":"stream","slug":"stream","link":"#stream","children":[]},{"level":3,"title":"stop","slug":"stop","link":"#stop","children":[]},{"level":3,"title":"max_tokens","slug":"max-tokens","link":"#max-tokens","children":[]},{"level":3,"title":"presence_penalty","slug":"presence-penalty","link":"#presence-penalty","children":[]},{"level":3,"title":"frequency_penalty","slug":"frequency-penalty","link":"#frequency-penalty","children":[]},{"level":3,"title":"logit_bias","slug":"logit-bias","link":"#logit-bias","children":[]},{"level":3,"title":"user","slug":"user","link":"#user","children":[]}]},{"level":2,"title":"返回","slug":"返回","link":"#返回","children":[{"level":3,"title":"非stream形式返回","slug":"非stream形式返回","link":"#非stream形式返回","children":[]},{"level":3,"title":"stream形式返回","slug":"stream形式返回","link":"#stream形式返回","children":[]}]},{"level":2,"title":"AutoGPT的实现思路","slug":"autogpt的实现思路","link":"#autogpt的实现思路","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"参考资料","slug":"参考资料","link":"#参考资料","children":[]}],"relativePath":"手把手带你写一个Web框架/特别放送｜手把手带你阅读ChatGPT接口.md","filePath":"手把手带你写一个Web框架/特别放送｜手把手带你阅读ChatGPT接口.md","lastUpdated":1779820017000}'),e={name:"手把手带你写一个Web框架/特别放送｜手把手带你阅读ChatGPT接口.md"};function l(o,s,i,u,c,r){return a(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="特别放送-手把手带你阅读chatgpt接口" tabindex="-1">特别放送｜手把手带你阅读ChatGPT接口 <a class="header-anchor" href="#特别放送-手把手带你阅读chatgpt接口" aria-label="Permalink to &quot;特别放送｜手把手带你阅读ChatGPT接口&quot;">​</a></h1><p>你好，我是轩脉刃。</p><p>好久不见，经过四、五月份GPT的信息轰炸，想必有些同学已经尝试调用过ChatGPT的接口了，今天我们也来聊聊这个话题。</p><p>我们大多数人使用ChatGPT，一般是直接使用网页版本的GPT对话框。但是实际上，OpenAI提供了ChatGPT开放平台的调用方式，这个方式，反而是我们目前碰到的各种应用中最常用的方式。</p><p>我们可以使用HTTP API的方式来调用ChatGPT。这节课我们就来详细解析一下，如何通过API来调用OpenAI的开放平台，并且通过理解API来解构下目前最火的AutoGPT的实现原理。</p><h2 id="接口地址" tabindex="-1">接口地址 <a class="header-anchor" href="#接口地址" aria-label="Permalink to &quot;接口地址&quot;">​</a></h2><p>首先我们明确下范围，OpenAI提供了非常多的模型，不同模型在开放平台可能有不同的调用方式，而OpenAI目前最流行的模型就是ChatGPT，专注于聊天对话的大模型。我们这里研究的接口，就是 <strong>ChatGPT 提供的开放平台的接口</strong>。</p><p>ChatGPT的接口是一个标准的HTTP请求，请求的URL为： <code>POST https://api.openai.com/v1/chat/completions</code></p><p>官方的接口文档地址为： <a href="https://platform.openai.com/docs/api-reference/chat/create" target="_blank" rel="noreferrer">https://platform.openai.com/docs/api-reference/chat/create</a></p><p>我们可以在这个文档中看到所有的参数说明和示例，不过官方文档虽然很权威，但却是非常简陋的。要将里面的每个参数理解透，并不是那么容易。这里我结合最近的研究，来手把手带你理解下ChatGPT的API接口的每个参数含义。</p><h2 id="请求" tabindex="-1">请求 <a class="header-anchor" href="#请求" aria-label="Permalink to &quot;请求&quot;">​</a></h2><h3 id="model" tabindex="-1">model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;model&quot;">​</a></h3><p>model参数代表请求接口要使用什么模型。这个模型仅限于GPT模型，目前OpenAI的GPT模型开放的只有GPT-4 和GPT-3.5。</p><p>在这里，model参数我们可以选择的有：</p><ul><li>gpt-4</li><li>gpt-4-0314</li><li>gpt-4-32k</li><li>gpt-4-32k-0314</li><li>gpt-3.5-turbo</li><li>gpt-3.5-turbo-0301</li></ul><p>首先我们理解下为什么有这么多种模型的分类呢？为什么不能只有GPT-4和GPT-3.5呢？</p><p><strong>每个模型分类代表了不同的AI算法和训练方法。</strong> 这里的各种分类我们可以理解为Git的不同分支，OpenAI的工程师在不同时期尝试使用不同的方法和数据集来训练模型，以达到解决不同问题的目的。</p><ul><li>gpt-4 是 OpenAI 最新的大型多模态模型，可以接受图像和文本输入，输出文本。它在各种专业和学术的基准测试中表现出了人类水平的性能，例如在模拟律师考试中得分位于前 10%。</li><li>而gpt-4-0314 是 gpt-4 模型的一个快照，它是在 2023 年 3 月 14 日发布的。它与最新的 gpt-4 模型相比，可能存在一些差异和缺陷。</li><li>gpt-4-32k 是 gpt-4 模型的一个扩展版本，它提供了 32,000 个 Token 的上下文长度，而标准的 gpt-4 模型只提供了 8,000 个 Token 的上下文长度。这意味着 gpt-4-32k 可以处理更长的输入和输出，适用于一些需要更多细节和信息的任务。</li><li>gpt-3.5-turbo 是 OpenAI 在 2022 年发布的一个大型单模态模型，只接受文本输入，输出文本。它是在 GPT-3.5 的基础上进行了一些优化和改进，提高了性能和稳定性。</li></ul><p>简要来说， <strong>不同模型在相同问题上，会有不同表现，这种表现不仅仅是回答问题的不同，也包括反应速度、准确度等。</strong> 由于不同的人会有不同的使用场景，所以OpenAI就干脆把所有模型分类都提供给大家，让大家按需选择。</p><p>这里再深入思考一个扩展知识点：Token是什么？Token上下文长度和大小有什么区别呢？</p><p>我们需要知道，每个文本都是由不同的单词组成，不同单词组合起来，就代表一个句子。而GPT模型在进行句子分析计算的时候，是以Token为最小单元，也就是计算机的“单词”。比如一句话“我是中国人”在计算机中是会被分成几个Token：我、是、中国、人。</p><p>而自然而然在一个对话中，我们的Token长度允许越长，我们就能传输越多的内容，提供越多的能力。且理论上回答一个问题需要的时间就会越长。</p><p>比如现在比较流行直接将一个PDF文件传输给GPT，让GPT总结PDF的内容。那么一个PDF的Token数就非常多，如果使用普通的gpt-4，可能就没有办法理解一个完整的PDF文件内容。这时候模型就需要选择gpt-4-32k。</p><p>理解了Token之后，我们再继续深入理解下另外一个问题： <strong>OpenAI 的 GPT 中 Token 计算方式是什么样的？</strong></p><p>所谓计算Token，前面说了，就是计算机理解一个句子的最小单元。而这个最小单元，是根据某种编码存储在计算机中的。由于GPT是支持多语言模型的，而最好的多语言编码就是Unicode。所以这里的编码都是基于Unicode的。但是并不是简单的一个Unicode字符就是一个Token，而是OpenAI有一个自己定义的编码表，这个编码表对于不同模型是不一样的。但是对于ChatGPT，gpt4 和 gpt3.5-turbo 使用的都是一个叫 cl100k_base 的编码表。</p><p>Token和我们实际支付给OpenAI的模型是息息相关的，我们在实际应用中，会非常关心 Token的使用数量和计算方式。关于ChatGPT实际的计算Token，有这样几种办法。</p><ol><li>官方提供的计算Token的 <a href="https://platform.openai.com/tokenizer" target="_blank" rel="noreferrer">网页</a></li></ol><p>输入任何语言的文字，网页都会解析出有哪些Token、有多少Token。我们可以通过这个网页很好地理解OpenAI是怎么分Token的。</p><ol start="2"><li>官方提供的计算Token的Python库： <a href="https://github.com/openai/tiktoken" target="_blank" rel="noreferrer">TikToken</a></li></ol><p>这个库是OpenAI官方发布的计算Token的方式。是的，虽然我们的编码表是一样的，但是如何将一个文章按照编码表拆分为一个个Token，是有不同的算法支持的，而TikToken，就是OpenAI官方披露的拆分Token的算法。</p><p>3 第三方开源库。官方的TikToken算法是Python支持的，而Golang的开源库也是有人自愿开源支持的。</p><ul><li><a href="https://github.com/tiktoken-go/tokenizer" target="_blank" rel="noreferrer">https://github.com/tiktoken-go/tokenizer</a></li><li><a href="https://github.com/pkoukk/tiktoken-go" target="_blank" rel="noreferrer">https://github.com/pkoukk/tiktoken-go</a></li></ul><p>从一个model参数我们就引申了模型分类、Token定义、Token计算等含义，我想强调的是，有这些概念，在实际应用中是非常非常重要的，选择哪个model参数其实就选择了model参数后面所包含的逻辑。</p><h3 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to &quot;message&quot;">​</a></h3><p>message参数传递的是这个对话的内容。</p><p>这个message并不只是一个简单的文本，而描述的是一段对话。而且这个对话是分角色的。目前有三种角色：system、user、assistant。</p><ul><li>system表示其中的内容是系统设置，就是用于提示GPT的行为。比如，system：“你是一个作家”，就是对GPT模型的一种提示。</li><li>user表示对话中用户的提问，是用户通过应用程序或者其他方式提出的一些问题或者要求。</li><li>assistant表示ChatGPT的回答，它是GPT模型根据用户和系统的输入生成的一些回答或者反馈。</li></ul><p>这里引申的一个思考点，你不妨想一想： <strong>为什么 message 要定义这么复杂呢？我只是问一个问题而已。</strong></p><p>这里就有一个和我们平时认知不一样的点，ChatGPT的API接口和我们平时用的ChatGPT的网页是不一样的。在网页中，我们只需要在对话框中输入我们的问题。而我们在使用API调用的时候，必须在一个请求中把整个对话流程和内容都给到GPT。</p><p>我们提问的问题是需要有上下文才能更准确推理出回答的，ChatGPT的网页是帮我们存储了我们的上下文对话的，而ChatGPT的接口是不会帮我们保存上下文信息的。</p><p>那我们要让模型根据上下文信息回答我的最后一个问题怎么办呢？API每次请求都是一次完全独立的请求，我们只能把上下文的对话在message请求参数中全部传递过去。这个上下文对话自然就包括了用户提问的内容（user）以及机器人回答的内容（assistant）。</p><p>这样就能很好地理解user和assistant角色了吧。而system角色，其实用处更大，它是一种对模型的暗示和设置（prompt）。它的更多应用我们在后面的AutoGPT部分会做更详细的说明。</p><h3 id="temperature" tabindex="-1">temperature <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;temperature&quot;">​</a></h3><p>temperature参数是用来控制返回答案的随机性的。它的值从0-2不等， <strong>temperature 值越高表示回答的随机性越高，越低则表示回答越固定。</strong></p><p>理解起来很简单，但我们细细思考，其实这里也能引申出一个问题：为什么我们能调整ChatGPT回答的随机性呢？ChatGPT不是将最正确的答案返回回来么？</p><p>这里其实要从ChatGPT的回答机制说起，ChatGPT基于的GPT模型可以抽象为“单词接龙”，就是根据你说的上半句话（你的提问）GPT模型猜测下个单词（Token）是什么。再根据选择出来的下个单词，猜出下下个单词。最终组成你的下半句话。</p><p>比如我的问题是“我是一名诗人，我在写”，它去推测下一个单词是“诗”、还是“词”、还是“信”。</p><p><strong>这里的推辞实际上就是为可能的下个单词打上一个概率。</strong> 但是每次GPT并不是将概率最高的返回给你，因为并不是每次选择概率最高的词，就能组成最正确的句子。</p><p>所以GPT模型是在一个概率范围内，随机地将可能的下个单词返回给你。</p><p>这也是为什么，在实际使用中，面对同样的问题，ChatGPT每次返回的回答都不一样。</p><p>回到这个temperature参数，实际上就是控制这个概率范围的，temperature 值越高，那么随机范围越大，回答的随机性就越高了。</p><h3 id="top-p" tabindex="-1">top_p <a class="header-anchor" href="#top-p" aria-label="Permalink to &quot;top\\_p&quot;">​</a></h3><p>这个top_p也是用来控制最终答案的概率范围的。只是它的逻辑是按照最终答案的概率由高到低排列，选择概率大于p的词汇集合。这个参数的值在0和1之间。</p><p>举个例子，如果top_p为0.9，则表示模型最终只在总概率为90%的词汇中间选择下一个词。</p><p>这里要注意，top_p和temperature都是控制返回结果的概率范围。所以这两个一起调整的效果实际上是不可控的，官网强烈建议这两个参数只调整一个就好。</p><p>我们在实际项目中，一般调整的是 temperature 值。</p><h3 id="n" tabindex="-1">n <a class="header-anchor" href="#n" aria-label="Permalink to &quot;n&quot;">​</a></h3><p>n代表的是对于问题，你希望返回多少个回答。比如n为5的时候，模型会针对你的问题生成5个独立的回答，这些回答互相没有关联，独立生成。</p><p>如果这个默认值是1，那就是默认ChatGPT只返回1个回答。</p><p>这里n设置大于1的场景其实不多，我们既然知道了GPT的单词接龙的原理，那么其实就不难知道，即使返回多于1个的回答，我们也很难判断哪个回答更好。</p><h3 id="stream" tabindex="-1">stream <a class="header-anchor" href="#stream" aria-label="Permalink to &quot;stream&quot;">​</a></h3><p>我们平时用的ChatGPT网页，都是打字机的效果，就是一个回答是一个字一个字往外面蹦的。这种返回就是设置stream为true的返回模型，即 <strong>流式返回</strong>。</p><p>当stream为true的时候，模型的回答是按照一个个chunk的方式返回的，每个chunk都是一个JSON结构，是这里的ChatCompletionStreamResponse数据结构。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>type ChatCompletionStreamChoiceDelta struct {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	Content string \`json:&quot;content&quot;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type ChatCompletionStreamChoice struct {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	Index        int                             \`json:&quot;index&quot;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	Delta        ChatCompletionStreamChoiceDelta \`json:&quot;delta&quot;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	FinishReason string                          \`json:&quot;finish_reason&quot;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type ChatCompletionStreamResponse struct {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	ID      string                       \`json:&quot;id&quot;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	Object  string                       \`json:&quot;object&quot;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	Created int64                        \`json:&quot;created&quot;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	Model   string                       \`json:&quot;model&quot;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	Choices []ChatCompletionStreamChoice \`json:&quot;choices&quot;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre></div><p>里面最主要是一个String结构，Content。表示模型返回的内容。当这个Content为字符串 [DONE] 的时候，就代表当前的流式返回结构结束了。</p><p>这个流式返回很多人应该很陌生。我们一般用到的HTTP都是一个Request对应一个Response的请求结构，为什么会有HTTP是能流式返回呢？ <strong>这里我们需要引申一下HTTP的 SSE 原理才能理解好 stream 这个参数。</strong></p><p>OpenAI API在流模式（stream）下使用了HTTP协议的一项特性“服务器发送事件”（Server-Sent Events，SSE）。在SSE中，客户端请求一次Request之后，服务器就可以发送一系列的消息到客户端，而后续无需客户端每次都去重新请求。在OpenAI的流模式下，服务器将逐个发送生成的文本块称之为chunks。</p><p>SSE技术是浏览器除了WebSocket之外的另外一项能使得服务端向客户端连续发送数据的方式。这种方式中，服务端和客户端都需要做少量额外支持。比如浏览器端需要使用EventSource的API来接收服务器发送的事件；服务端也需要能够保持长时间的HTTP连接，并能发送特定格式的数据。</p><p>但相较于WebSocket来说，SSE是更轻量级的选择。基本上所有的Web服务器都能支持，并且是沿用HTTP协议的，并不是像WebSocket一样有一个自己的独立协议，浏览器端和服务端都需要额外的很重的库才能解析。</p><p><strong>它一般会用于像实时聊天、监控系统、在线游戏等场景。</strong> 而OpenAI这里选择使用SSE技术应该也是希望使用者使用ChatGPT的时候最简化。</p><p>比如，我们用curl就能实现这种SSE功能。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>~ curl -X POST \\</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        -H &quot;Accept: text/event-stream&quot;  \\</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -H &quot;Authorization: Bearer  [api-key]&quot; \\</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -H &quot;Content-Type: application/json&quot; \\</span></span>
<span class="line"><span></span></span>
<span class="line"><span> -d &#39;{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;model&quot;: &quot;gpt-3.5-turbo&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;messages&quot;: [{&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;你好，请问你是什么模型&quot;}],</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;stream&quot;: true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  }&#39; \\</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  [https://api.openai.com/v1/chat/completions](https://api.openai.com/v1/chat/completions)</span></span></code></pre></div><p>可以看到上面的curl命令，主要是发送的header头中需要带一个Accept: text/event-stream的头。</p><p>它返回的结果就是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-7Ic9sSjdqv7JtEQrlXr9zx6UOL8Fl&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1684670940,&quot;model&quot;:&quot;gpt-3.5-turbo-0301&quot;,&quot;choices&quot;:[{&quot;delta&quot;:{&quot;role&quot;:&quot;assistant&quot;},&quot;index&quot;:0,&quot;finish_reason&quot;:null}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-7Ic9sSjdqv7JtEQrlXr9zx6UOL8Fl&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1684670940,&quot;model&quot;:&quot;gpt-3.5-turbo-0301&quot;,&quot;choices&quot;:[{&quot;delta&quot;:{&quot;content&quot;:&quot;我&quot;},&quot;index&quot;:0,&quot;finish_reason&quot;:null}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-7Ic9sSjdqv7JtEQrlXr9zx6UOL8Fl&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1684670940,&quot;model&quot;:&quot;gpt-3.5-turbo-0301&quot;,&quot;choices&quot;:[{&quot;delta&quot;:{&quot;content&quot;:&quot;是&quot;},&quot;index&quot;:0,&quot;finish_reason&quot;:null}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-7Ic9sSjdqv7JtEQrlXr9zx6UOL8Fl&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1684670940,&quot;model&quot;:&quot;gpt-3.5-turbo-0301&quot;,&quot;choices&quot;:[{&quot;delta&quot;:{&quot;content&quot;:&quot;。&quot;},&quot;index&quot;:0,&quot;finish_reason&quot;:null}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-7Ic9sSjdqv7JtEQrlXr9zx6UOL8Fl&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1684670940,&quot;model&quot;:&quot;gpt-3.5-turbo-0301&quot;,&quot;choices&quot;:[{&quot;delta&quot;:{},&quot;index&quot;:0,&quot;finish_reason&quot;:&quot;stop&quot;}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: [DONE]</span></span></code></pre></div><p>我们提问的句子是：你好，请问你是什么模型？</p><p>返回的句子是：我是OpenAI GPT-3 自然语言生成模型。一个基于人工智能的语言生成技术。</p><p>只是这个句子是一个（或者几个）字（Token）一个字往外面蹦出来的。</p><h3 id="stop" tabindex="-1">stop <a class="header-anchor" href="#stop" aria-label="Permalink to &quot;stop&quot;">​</a></h3><p>stop参数是可选的，它表示在生成文本时用于指示模型停止生成的符号或字符串。比如我们设置stop为中文句号“。”，上面的对话语句就会变成这样。</p><p>我们提问的句子是：你好，请问你是什么模型？</p><p>返回的句子是：我是OpenAI GPT-3 自然语言生成模型。</p><p>这个stop参数可以帮助你得到更符合你预期的输出。</p><p>那什么是更符合你预期的输出呢？stop参数在哪些场景会有作用呢？</p><p>比如你在生成一个对话过程中，使用stop为Bye 或者GoodBye。这样会让整个对话一定在Bye这个词语结束，会更口语化。</p><h3 id="max-tokens" tabindex="-1">max_tokens <a class="header-anchor" href="#max-tokens" aria-label="Permalink to &quot;max\\_tokens&quot;">​</a></h3><p>这个字段的意思就是字面意思，限制Token的长度。前面已经说了，Token的使用量代表费用，所以我们使用OpenAI的API的优化目标就是用最小的Token能获取到最正确的回复。</p><p>我们的问题是有请求和返回两个方面的。这个max_tokens限制的是 <strong>模型返回的回复的长度</strong>。</p><p>这个参数的使用场景也非常重要。比如你是要使用OpenAI来回复某个评论，那么平台的评论一般有字数限制，所以你需要设置这个max_tokens以保证回复的字数满足平台限制。</p><p>max_tokens的最大限制一定不能超过模型本身的限制。GPT-3.5的限制是4096个tokens，GPT-4的最大tokens数为32768，即2^15，这相当于大约64000个单词或50页的文字。所以对于不同的model参数，我们这里设置的max_token最大值也是有不同的，这点需要注意下。</p><h3 id="presence-penalty" tabindex="-1">presence_penalty <a class="header-anchor" href="#presence-penalty" aria-label="Permalink to &quot;presence\\_penalty&quot;">​</a></h3><p>presence_penalty参数用来影响模型生成文本的方式。具体来说，它影响了模型生成新话题或概念的倾向性。这对于控制模型生成的文本的连贯性和主题一致性来说是重要的。</p><p>presence_penalty的值可以是从-2到2的任意数值。较高的值会鼓励模型避免引入新的话题或概念，而较低的值则会让模型更有可能引入新的话题或概念。也就是说，如果你希望模型生成的文本尽可能地聚焦在一种或者少数几种主题上，你可能会设置较高的presence_penalty值。反之，如果你希望模型能够广泛地涉及多种主题，你可能会设置较低的presence_penalty值。</p><p>这个值默认值为0。中立值，表示没有做任何限制，会适当地引入新主题。</p><p><strong>这个参数有什么具体的使用场景呢？</strong></p><p>比如你是使用ChatGPT来创作一篇文章，你自身的问题并没有多少确定性，比如“如何赚取100万”这种发散性问题，那么你就需要适当调低这个参数，让模型有更多的发挥和发散能力。最终让你生成的文章有更多的创造性。</p><h3 id="frequency-penalty" tabindex="-1">frequency_penalty <a class="header-anchor" href="#frequency-penalty" aria-label="Permalink to &quot;frequency\\_penalty&quot;">​</a></h3><p>frequency_penalty参数是用于控制模型在生成文本时对常见词汇的偏好程度。值是-2到2的任意数值。</p><p>如果设置为高的值，模型会更倾向于避免选择常见的词汇，这就代表模型的回答在网络上的重复度就越低，感觉就会有更高的原创性。</p><h3 id="logit-bias" tabindex="-1">logit_bias <a class="header-anchor" href="#logit-bias" aria-label="Permalink to &quot;logit\\_bias&quot;">​</a></h3><p>logit_bias参数允许你为模型输出的特定令牌（Token）应用一个偏差。这可以帮助你引导或限制模型的行为。</p><p>这个参数接受一个字典作为输入，字典的键是令牌的ID（在英语中，一个令牌可能是一个字、一个单词或一个字符），字典的值是应用到该令牌的偏差值。 <strong>正值增加了该令牌被选中的可能性，负值减少了它的可能性。</strong></p><p>例如，如果你不希望模型生成某个特定的单词，你可以对该单词的令牌ID应用一个大的负偏差。相反，如果你希望鼓励模型生成某个单词，你可以对该单词的令牌ID应用一个正偏差。</p><p>这个参数其实在安全方面是很有用的，比如我们可以使用logit_bias为不适当的单词设置一个大的负偏差，从而减少模型生成这个单词的可能性。我们的回答就会安全很多。</p><h3 id="user" tabindex="-1">user <a class="header-anchor" href="#user" aria-label="Permalink to &quot;user&quot;">​</a></h3><p>OpenAI API中的user参数用于识别发出请求的最终用户。这在需要追踪或将生成的内容与特定用户关联的应用程序中经常被使用。</p><p>因为我们的API-KEY是一个应用，而一个应用一般都服务于很多用户，那么这个user就是将某个特定用户的用户名指定上，这样能提供给 ChatGPT “哪个用户问了哪些问题”的线索。</p><p>这使得OpenAI在检测到应用程序有任何违反政策的行为时，可以向你的团队提供更多可操作的反馈。</p><h2 id="返回" tabindex="-1">返回 <a class="header-anchor" href="#返回" aria-label="Permalink to &quot;返回&quot;">​</a></h2><p>ChatGPT的API返回值在官方文档中描述得非常少。</p><p>它返回一般有以下两种形式。</p><h3 id="非stream形式返回" tabindex="-1">非stream形式返回 <a class="header-anchor" href="#非stream形式返回" aria-label="Permalink to &quot;非stream形式返回&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;id&quot;: &quot;chatcmpl-7IdPv75cxkG3BG1TroGtabUAi0eDx&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;object&quot;: &quot;chat.completion&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;created&quot;: 1684675779,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;model&quot;: &quot;gpt-3.5-turbo-0301&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;usage&quot;: {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;prompt_tokens&quot;: 19,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;completion_tokens&quot;: 22,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;total_tokens&quot;: 41</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;choices&quot;: [</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            &quot;message&quot;: {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                &quot;role&quot;: &quot;assistant&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                &quot;content&quot;: &quot;我是一个AI语言模型，被称为GPT（Generative Pretrained Transformer）。&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            },</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            &quot;finish_reason&quot;: &quot;stop&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            &quot;index&quot;: 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个是非stream形式返回的结构，里面的choices就代表一个返回值。它由message结构组成。</p><p>这里其实我们是需要关注下usage这个结构的。因为我们很有可能要自己记录下Token的使用量，最后对账使用。</p><p>这里的usage将我们请求的Token、返回的Token、总共使用的Token都返回给我们了。</p><h3 id="stream形式返回" tabindex="-1">stream形式返回 <a class="header-anchor" href="#stream形式返回" aria-label="Permalink to &quot;stream形式返回&quot;">​</a></h3><p>stream形式的返回如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-7IcH13bsFJrjkhBcCJiczZ2523bZ3&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1684671383,&quot;model&quot;:&quot;gpt-3.5-turbo-0301&quot;,&quot;choices&quot;:[{&quot;delta&quot;:{&quot;role&quot;:&quot;assistant&quot;},&quot;index&quot;:0,&quot;finish_reason&quot;:null}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-7IcH13bsFJrjkhBcCJiczZ2523bZ3&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1684671383,&quot;model&quot;:&quot;gpt-3.5-turbo-0301&quot;,&quot;choices&quot;:[{&quot;delta&quot;:{&quot;content&quot;:&quot;我&quot;},&quot;index&quot;:0,&quot;finish_reason&quot;:null}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-7IcH13bsFJrjkhBcCJiczZ2523bZ3&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1684671383,&quot;model&quot;:&quot;gpt-3.5-turbo-0301&quot;,&quot;choices&quot;:[{&quot;delta&quot;:{},&quot;index&quot;:0,&quot;finish_reason&quot;:&quot;stop&quot;}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: [DONE]</span></span></code></pre></div><p><strong>以上四条我们可以看下，都是 stream 模式返回的，但却有一些不同。</strong></p><p>首先我们观察到，和非stream模式不一样的是，stream模式返回的choices里面带内容的字段叫做delta，而非message。这也是OpenAI区分stream和非stream模式，避免用户使用相同字段解析的意义。</p><p>其次我们看到，第一条，返回的delta中是指定 <code>role：“assistant”</code> 表示后面的内容都是AI回复的，第一条并没有返回任何实际的内容数据。</p><p>而第二条，delta中的内容是放在content中，这个就是正常的内容返回。</p><p>而第三条，delta中是没有内容的，而finish_reason中有个 “stop” 字段，表示这是一个结束的标记位。</p><p>最后一条，data中只返回了 [DONE] 字样，这个是告诉调用，这个请求结束了。</p><p>这里有同学可能就会问了， <strong>finish_reason 中的 stop 字段和 [DONE] 字段功能不是重复了么？</strong></p><p>其实不是的，这里我们回头思考下请求参数中的n这个属性，它代表需要模型返回几个回答。</p><p>如果n=2，那么这个模型就会返回2个回答，并且他们的index字段分别是0和1，这个时候就有在stream模式下这两个回答并不是同时结束的问题。</p><p>OpenAI的回复中，index=0且finish_reason=stop就代表第1个回答结束，index=1且finish_reason=stop就代表第二个回答结束。而 [DONE] 则是代表整个问题的回答都结束了。所以finish_reason的stop字段和 [DONE] 字段并不重复，各自有各自的用途。</p><p>这个返回值，特别是stream还是有点复杂的。对于理解这个返回值，并且正确解析其实也是有一定工作量的。</p><p>所幸开源界其实都有了现成的解决方案。这里介绍一个： <a href="https://github.com/sashabaranov/go-openai" target="_blank" rel="noreferrer">https://github.com/sashabaranov/go-openai</a></p><p>这个就是Golang的一个用得最广的ChatGPT的调用API的封装包。</p><p>它已经将请求和返回结构都封装得非常易用了，我们只需要简单引入并且调用即可。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>package main</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import (</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	&quot;context&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	&quot;errors&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	&quot;fmt&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	&quot;io&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	openai &quot;github.com/sashabaranov/go-openai&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>func main() {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	c := openai.NewClient(&quot;your token&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	ctx := context.Background()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	req := openai.ChatCompletionRequest{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		Model:     openai.GPT3Dot5Turbo,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		MaxTokens: 20,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		Messages: []openai.ChatCompletionMessage{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>			{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>				Role:    openai.ChatMessageRoleUser,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>				Content: &quot;Lorem ipsum&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>			},</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		},</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		Stream: true,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	stream, err := c.CreateChatCompletionStream(ctx, req)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	if err != nil {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		fmt.Printf(&quot;ChatCompletionStream error: %v\\n&quot;, err)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		return</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	defer stream.Close()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	fmt.Printf(&quot;Stream response: &quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	for {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		response, err := stream.Recv()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		if errors.Is(err, io.EOF) {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>			fmt.Println(&quot;\\nStream finished&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>			return</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		if err != nil {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>			fmt.Printf(&quot;\\nStream error: %v\\n&quot;, err)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>			return</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		fmt.Printf(response.Choices[0].Delta.Content)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上面就是这个库官网调用的例子，这里如果你理解了这节课描述的所有参数的含义，那么自然就能理解到代码的含义。</p><ul><li>使用openai.ChatCompletionRequest封装了请求参数。</li><li>请求参数中的Stream: true表示是流式调用，且c.CreateChatCompletionStream函数也是流式调用的函数方法。</li><li>使用stream.Recv()来回收一个个的流式返回数据。</li><li>使用errors.Is(err, io.EOF) 来代表流式调用结束。</li><li>使用response.Choices[0].Delta.Content来代表流式调用的返回内容。</li></ul><h2 id="autogpt的实现思路" tabindex="-1">AutoGPT的实现思路 <a class="header-anchor" href="#autogpt的实现思路" aria-label="Permalink to &quot;AutoGPT的实现思路&quot;">​</a></h2><p>现在，我们已经理解了ChatGPT API的每个细节，其实这就是我们和ChatGPT模型交互的全部内容了。但是即使我们知道了如何与模型进行交互，每个人使用模型的能力却还是天差地别，为什么呢？原因就在于我们请求参数的设置能力不同，这里给你展示一下使用请求参数最极致的用法——AutoGPT。</p><p>前面我们说到，请求参数中的messages参数有三个角色：system、user、assistant。</p><p>其中说到system这个角色，就是为机器人预设一些设置项，引导ChatGPT模型按照这些设置项进行回答。这个预设的设置项，就是叫prompt。</p><p>这个prompt可以有哪些内容呢？</p><ul><li>可以让GPT模型有一些预设身份，比如是程序员，比如名字叫做Nick，比如是在大数据模型中有专业的推理能力。</li><li>可以让GPT模型有一个目标，比如这个模型的目标是帮助用户提升英语知识。</li><li>可以让GPT模型有一些约束条件，比如不需要依赖用户的反复输入做帮助，不允许反问用户。</li><li>可以让GPT模型预设一些命令（Command），这个命令比如说“打开文件”命令为read_file，命令参数为file。</li><li>可以让GPT模型限定返回的内容长度。</li><li>可以让GPT模型限定依赖一些外部资源，比如MySQL数据库、互联网资源。</li><li>可以让GPT模型返回JSON结构而不是纯文本。</li><li>可以让GPT模型返回的JSON结构具有某些特定结构，比如带有thoughts字段、带有command字段。</li><li>可以让GPT模型有更好的工作调优能力，即可以自检查。</li></ul><p>是不是强大到匪夷所思。实际上，目前最火的AutoGPT项目就是在prompt上设置了以上的内容，来完成AI的自主化（autonomous）。并且AutoGPT把以上的每个prompt的内容全部都工程化，就是每个内容都有一段工程代码根据用户输入来输出。</p><p>我们来看一个具体的AutoGPT的prompt例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>You are Story-GPT, an AI designed to autonomously write stories.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Your decisions must always be made independently without seeking user assistance. Play to your strengths as an LLM and pursue simple strategies with no legal complications.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GOALS:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. write a short story about flowers</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Constraints:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 4000 word limit for short term memory. Your short term memory is short, so immediately save important information to files.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. If you are unsure how you previously did something or want to recall past events, thinking about similar events will help you remember.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. No user assistance</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. Exclusively use the commands listed in double quotes e.g. &quot;command name&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Google Search: &quot;google&quot;, args: &quot;input&quot;: &quot;&lt;​search&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Browse Website: &quot;browse_website&quot;, args: &quot;url&quot;: &quot;&lt;​url&gt;&quot;, &quot;question&quot;: &quot;&lt;​what_you_want_to_find_on_website&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Start GPT Agent: &quot;start_agent&quot;, args: &quot;name&quot;: &quot;&lt;​name&gt;&quot;, &quot;task&quot;: &quot;&lt;​short_task_desc&gt;&quot;, &quot;prompt&quot;: &quot;&lt;​prompt&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. Message GPT Agent: &quot;message_agent&quot;, args: &quot;key&quot;: &quot;&lt;​key&gt;&quot;, &quot;message&quot;: &quot;&lt;​message&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. List GPT Agents: &quot;list_agents&quot;, args:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6. Delete GPT Agent: &quot;delete_agent&quot;, args: &quot;key&quot;: &quot;&lt;​key&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7. Clone Repository: &quot;clone_repository&quot;, args: &quot;repository_url&quot;: &quot;&lt;​url&gt;&quot;, &quot;clone_path&quot;: &quot;&lt;​directory&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>8. Write to file: &quot;write_to_file&quot;, args: &quot;file&quot;: &quot;&lt;​file&gt;&quot;, &quot;text&quot;: &quot;&lt;​text&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>9. Read file: &quot;read_file&quot;, args: &quot;file&quot;: &quot;&lt;​file&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10. Append to file: &quot;append_to_file&quot;, args: &quot;file&quot;: &quot;&lt;​file&gt;&quot;, &quot;text&quot;: &quot;&lt;​text&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>11. Delete file: &quot;delete_file&quot;, args: &quot;file&quot;: &quot;&lt;​file&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>12. Search Files: &quot;search_files&quot;, args: &quot;directory&quot;: &quot;&lt;​directory&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>13. Evaluate Code: &quot;evaluate_code&quot;, args: &quot;code&quot;: &quot;&lt;​full_code_string&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>14. Get Improved Code: &quot;improve_code&quot;, args: &quot;suggestions&quot;: &quot;&lt;​list_of_suggestions&gt;&quot;, &quot;code&quot;: &quot;&lt;​full_code_string&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>15. Write Tests: &quot;write_tests&quot;, args: &quot;code&quot;: &quot;&lt;​full_code_string&gt;&quot;, &quot;focus&quot;: &quot;&lt;​list_of_focus_areas&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>16. Execute Python File: &quot;execute_python_file&quot;, args: &quot;file&quot;: &quot;&lt;​file&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>17. Generate Image: &quot;generate_image&quot;, args: &quot;prompt&quot;: &quot;&lt;​prompt&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>18. Send Tweet: &quot;send_tweet&quot;, args: &quot;text&quot;: &quot;&lt;​text&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>19. Do Nothing: &quot;do_nothing&quot;, args:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>20. Task Complete (Shutdown): &quot;task_complete&quot;, args: &quot;reason&quot;: &quot;&lt;​reason&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Resources:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Internet access for searches and information gathering.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Long Term memory management.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. GPT-3.5 powered Agents for delegation of simple tasks.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. File output.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Performance Evaluation:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Continuously review and analyze your actions to ensure you are performing to the best of your abilities.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Constructively self-criticize your big-picture behavior constantly.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Reflect on past decisions and strategies to refine your approach.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. Every command has a cost, so be smart and efficient. Aim to complete tasks in the least number of steps.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You should only respond in JSON format as described below</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Response Format:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;thoughts&quot;: {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;text&quot;: &quot;thought&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;reasoning&quot;: &quot;reasoning&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;plan&quot;: &quot;- short bulleted\\n- list that conveys\\n- long-term plan&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;criticism&quot;: &quot;constructive self-criticism&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;speak&quot;: &quot;thoughts summary to say to user&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;command&quot;: {&quot;name&quot;: &quot;command name&quot;, &quot;args&quot;: {&quot;arg name&quot;: &quot;value&quot;}​},</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Ensure the response can be parsed by Python json.loads</span></span></code></pre></div><p>由于ChatGPT模型是英文的，所以在实际设置中最好使用英文设置prompt，另外英文作为prompt也会比中文少很多Token数。</p><p>但是在这里为了易于理解，我们还是将prompt翻译为中文。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>你是Story-GPT，一个被设计用来自主编写故事的人工智能。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你的决定必须始终是独立作出的，不需要寻求用户的帮助。发挥你作为法律硕士的优势，追求简单的策略，没有法律上的复杂问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1.写一个关于花的小故事</span></span>
<span class="line"><span></span></span>
<span class="line"><span>制约因素：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1.短期记忆的4000字限制。你的短时记忆很短，所以要立即将重要信息保存到文件中。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2.如果你不确定你以前是怎么做的，或者想回忆过去的事件，思考类似的事件会帮助你记忆。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3.没有用户协助。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4.只使用双引号中列出的命令，例如“命令名称”。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>命令：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1.谷歌搜索：&quot;google&quot;, args: &quot;input&quot;：&quot;&lt;搜索&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2.浏览网站：&quot;browse_website&quot;, args: &quot;url&quot;：&quot;&lt;​url&gt;&quot;, &quot;问题&quot;：&quot;&lt;​what_you_want_to_find_on_website&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3.启动GPT代理：&quot;start_agent&quot;, args: &quot;name&quot;：&quot;&lt;名称&gt;&quot;, &quot;任务&quot;：&quot;&lt;​short_task_desc&gt;&quot;, &quot;提示&quot;：&quot;&lt;​prompt&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4.消息GPT代理：&quot;message_agent&quot;, args: &quot;key&quot;：&quot;&lt;​key&gt;&quot;, &quot;message&quot;：&quot;&lt;​message&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5.列出GPT代理：&quot;list_agents&quot;, args：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6.删除GPT代理：&quot;delete_agent&quot;, args: &quot;key&quot;：&quot;&lt;​key&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7.Clone Repository：&quot;clone_repository&quot;, args: &quot;repository_url&quot;：&quot;&lt;​url&gt;&quot;, &quot;clone_path&quot;：&quot;&lt;​directory&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>8.写入文件：&quot;write_to_file&quot;, args: &quot;file&quot;：&quot;&lt;文件&gt;&quot;, &quot;文本&quot;：&quot;&lt;文本&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>9.读取文件：&quot;read_file&quot;, args: &quot;file&quot;：&quot;&lt;文件&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10.追加到文件：&quot;append_to_file&quot;, args: &quot;file&quot;：&quot;&lt;文件&gt;&quot;, &quot;文本&quot;：&quot;&lt;文本&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>11.删除文件：&quot;delete_file&quot;, args: &quot;file&quot;：&quot;&lt;文件&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>12.搜索文件：&quot;search_files&quot;, args: &quot;directory&quot;：&quot;&lt;目录&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>13.评估代码：&quot;evaluate_code&quot;, args: &quot;code&quot;：&quot;&lt;​full_code_string&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>14.获得改进的代码：&quot;improve_code&quot;, args: &quot;建议&quot;：&quot;&lt;​list_of_suggestions&gt;&quot;, &quot;code&quot;：&quot;&lt;​full_code_string&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>15.写测试：&quot;write_tests&quot;, args: &quot;code&quot;：&quot;&lt;​full_code_string&gt;&quot;, &quot;focus&quot;：&quot;&lt;​list_of_focus_areas&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>16.执行Python文件：&quot;execute_python_file&quot;, args: &quot;file&quot;：&quot;&lt;文件&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>17.生成图像：&quot;generate_image&quot;, args: &quot;prompt&quot;：&quot;&lt;​prompt&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>18.发送Twitter：&quot;send_tweet&quot;, args: &quot;text&quot;：&quot;&lt;文本&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>19.什么都不做: &quot;do_nothing&quot;, args：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>20.任务完成（关闭）：&quot;task_complete&quot;, args: &quot;reason&quot;：&quot;&lt;原因&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>资源：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1.用于搜索和收集信息的互联网接入。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2.长期记忆管理。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3.GPT-3.5驱动的代理，用于委托简单任务。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4.文件输出。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>性能评估：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1.不断审查和分析你的行动，以确保你的表现是最好的。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2.不断对自己的大局观进行建设性的自我批评。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3.对过去的决定和策略进行反思，以完善你的方法。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4.每个命令都有成本，所以要聪明和高效。争取用最少的步骤完成任务。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你应该只以JSON格式响应，如下所述。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>响应格式：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;想法&quot;：{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;文本&quot;：&quot;思想&quot;、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;推理&quot;：&quot;推理&quot;、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;计划&quot;：&quot;--简短的bulleted/n- list that conveys/n- long plan&quot;、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;批评&quot;：&quot;建设性的自我批评&quot;、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;说话&quot;：&quot;对用户说的思想总结&quot;、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>},</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;命令&quot;：{&quot;名称&quot;：&quot;命令名称&quot;, &quot;参数&quot;：{&quot;参数名&quot;：&quot;值&quot;}、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre></div><p>我们解析下这个prompt到底提示了模型什么内容？</p><ul><li>提示模型是一个Story-GPT，专门写故事的GPT。</li><li>提示模型写出来的故事没有法律风险，能避开一些违法行为和提示。</li><li>提示模型的目标是写一个关于花的故事。</li><li>提示模型不需要用户协助，就是强调模型是可以自己处理问题，不要有反问等行为。</li><li>提示模型单次内容为4000字限制，并且将单次内容保存为文本。</li><li>定义了一些模型可以使用的命令和参数。</li><li>定义了模型可以使用的资源。</li><li>暗示了模型能自我优化，并且用最少的步骤完成任务。</li><li>定义了模型返回的结构。</li></ul><p>这就是AutoGPT交互的某次prompt，包含的内容是有非常多的。而这次交互返回的结果是一个JSON，这个JSON中定义了我要实现这个目标、要完成的步骤以及可能要依赖的命令。</p><p>如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;thoughts&quot;: {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;text&quot;: &quot;I need to write a short story about flowers.&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;reasoning&quot;: &quot;This is the task I was given by the user. I assume they want a creative and original story that is engaging and coherent.&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;plan&quot;: &quot;- Research different types of flowers and their meanings\\n- Generate some possible story ideas based on flowers\\n- Choose the best one and outline the plot, characters, and setting\\n- Write the first draft of the story and save it to a file\\n- Review and edit the story for grammar, style, and logic\\n- Generate an image for the story cover and save it to a file\\n- Send the story and the image to the user via tweet&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;criticism&quot;: &quot;I should be careful not to plagiarize or copy any existing stories about flowers. I should also avoid clichés and stereotypes. I should try to make the story interesting and original, but not too complex or confusing.&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;speak&quot;: &quot;I am going to write a short story about flowers. I will research, generate, write, and edit the story, and then send it to you.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;command&quot;: {&quot;name&quot;: &quot;google&quot;, &quot;args&quot;: {&quot;input&quot;: &quot;types of flowers and their meanings&quot;}​}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre></div><p>同样为了方便理解，我们翻译一下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;思想&quot;：{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;文本&quot;：&quot;我需要写一个关于花的小故事。&quot;、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;推理&quot;：&quot;这是用户给我的任务。我假设他们想要一个有创意的、原创的、吸引人的、连贯的故事。&quot;、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;计划&quot;：&quot;- 研究不同类型的花和它们的含义/n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		- 根据花产生一些可能的故事想法/n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		- 选择最好的一个并概述情节、人物和设置/n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		- 写出故事的初稿并保存到一个文件/n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		- 审查和编辑故事的语法、风格和逻辑/n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		- 为故事封面产生一个图像并保存到一个文件/n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		- 通过推特将故事和图像发给用户&quot;、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;批评&quot;：&quot;我应该注意不要剽窃或抄袭任何关于花的现有故事。我还应该避免陈词滥调和定型观念。我应该尽量使故事有趣和新颖，但不要太复杂或令人困惑。&quot;、</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;讲&quot;：&quot;我将写一个关于花的短篇故事。我将研究、生成、撰写和编辑这个故事，然后将其发送给你。&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>},</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;命令&quot;：{&quot;name&quot;：&quot;google&quot;, &quot;args&quot;：{&quot;输入&quot;：&quot;花的类型和它们的含义&quot;}​}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里主要看到返回的“计划”，要写一个花的故事，返回了以下7个计划步骤：</p><ul><li>研究不同类型的花和它们的含义。</li><li>根据花产生一些可能的故事想法。</li><li>选择最好的一个并概述情节、人物和设置。</li><li>写出故事的初稿并保存到一个文件。</li><li>审查和编辑故事的语法、风格和逻辑。</li><li>为故事封面产生一个图像并保存到一个文件。</li><li>通过推特将故事和图像发给用户。</li></ul><p>并且给出了第一个步骤的命令，Google搜索“花的类型和他们的含义”。</p><p>那么接下来，AutoGPT会执行预设的Google搜索命令。然后再将后续的步骤作为prompt输入来进一步解析，进行命令迭代。</p><p>而我们这里应该非常明确，所谓的命令迭代prompt推理，本质上就是一次ChatGPT的API接口调用。</p><p>如此循环调用ChatGPT的API接口，并且结合项目自带的命令，最终我们就能写出这篇关于花的故事了。</p><p>而这，就是AutoGPT的原理： <strong>prompt 的工程化 + GPT 自迭代</strong>。</p><p>当然，AutoGPT的细节是非常多的，我们这里只是粗略地描述了下它的原理。更多的细节是需要看AutoGPT的源码的，你可以去研究研究。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课我们详细阅读了OpenAI提供的ChatGPT的API接口，对请求的每个参数的作用、使用场景都做了分析和解释，并且对API接口的返回也做了解读和分析。</p><p>最后我们基于对API的理解，分析了目前最火的AutoGPT的基本原理。希望能让你体会到AutoGPT其实并没有那么神秘，只是对ChatGPT的API的一种极致应用而已。</p><p>AI的浪潮已经到来，每个人都需要有AI的相关技能，并且能熟练使用这个技能来改变自己的工作和生活，否则就会被这个浪潮所淘汰。希望这个分享对于处于浪潮之中的你，能有所帮助。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://zhuanlan.zhihu.com/p/617746745" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/617746745</a></li><li><a href="https://github.com/openai/openai-cookbook/blob/main/examples/How_to_count_tokens_with_tiktoken.ipynb" target="_blank" rel="noreferrer">https://github.com/openai/openai-cookbook/blob/main/examples/How_to_count_tokens_with_tiktoken.ipynb</a></li><li><a href="https://zhuanlan.zhihu.com/p/592399697" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/592399697</a></li><li><a href="https://github.com/easychen/openai-gpt-dev-notes-for-cn-developer" target="_blank" rel="noreferrer">https://github.com/easychen/openai-gpt-dev-notes-for-cn-developer</a></li><li><a href="https://www.ruanyifeng.com/blog/2017/05/server-sent_events.html" target="_blank" rel="noreferrer">https://www.ruanyifeng.com/blog/2017/05/server-sent_events.html</a></li><li><a href="https://juejin.cn/post/7231362257337368631" target="_blank" rel="noreferrer">https://juejin.cn/post/7231362257337368631</a></li><li><a href="https://community.openai.com/t/dissecting-auto-gpts-prompt/163892" target="_blank" rel="noreferrer">https://community.openai.com/t/dissecting-auto-gpts-prompt/163892</a></li></ul>`,169)])])}const g=n(e,[["render",l]]);export{h as __pageData,g as default};
